import { formatMoney } from "./format.ts";

export interface Line {
  name: string;
  cents: number;
  quantity: number;
}

export interface Customer {
  id: string;
  orders: number;
}

export function lineTotal(line: Line): number {
  return line.cents * line.quantity;
}

export function orderTotal(lines: Line[]): number {
  return lines.reduce((sum, line) => sum + lineTotal(line), 0);
}

export const LOYALTY_ORDERS = 5;
export const LOYALTY_PERCENT = 10;

export interface Discounted {
  total: number;
  message: string | null;
}

export function loyaltyDiscount(customer: Customer, cents: number): Discounted {
  if (customer.orders <= LOYALTY_ORDERS) return { total: cents, message: null };
  const saved = Math.round((cents * LOYALTY_PERCENT) / 100);
  return { total: cents - saved, message: `Loyalty discount: you saved ${formatMoney(saved)}` };
}

